pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameter is the assertionId whose policy we query.
    function testFuzz_property(bytes32 assertionId) public {
        // No restrictive assumes: all bytes32 are admissible.
        // Call the contract and read the returned AssertionPolicy via the public getter.
        // We only need to observe the arbitrateViaEscalationManager field by decoding the returned tuple.

        // The function returns a struct; Solidity returns it as multiple values. We call it via low-level staticcall
        // to capture the raw return data and decode the specific bool field position robustly across compiler layouts.

        // Prepare calldata for getAssertionPolicy(bytes32)
        bytes memory sig = abi.encodeWithSignature("getAssertionPolicy(bytes32)", assertionId);
        (bool ok, bytes memory ret) = address(c).staticcall(sig);
        // Ensure the call succeeds on both reference and mutant; both implementations are view and do not revert.
        // But we still handle the boolean per the problem rules: assertTrue must read c. We decode the bool here.
        require(ok, "call failed");

        // The returned struct has four bools in order: blockAssertion, arbitrateViaEscalationManager, discardOracle, validateDisputers
        // Solidity ABI packs returned tuple as (bool,bool,bool,bool). Decode accordingly.
        (bool blockAssertion, bool arbitrateViaEscalationManager, bool discardOracle, bool validateDisputers) = abi.decode(ret, (bool, bool, bool, bool));

        // The universal property: arbitrateViaEscalationManager must be false for ALL inputs on the reference.
        // This single assert reads c's behavior (the decoded return) and will fail on the mutant for any assertionId
        // where the mutant sets that field to true (some inputs exist — fuzz will find them).
        assertTrue(!arbitrateViaEscalationManager);
    }
}

