    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: identifier, time, ancillaryData
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Keep the domain wide; no restrictive assumes

        // Call getPrice via try/catch to observe whether it returns successfully (reference: should not revert)
        bool ok;
        int256 val1;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 v) {
            ok = true;
            val1 = v;
        } catch {
            ok = false;
            val1 = int256(0);
        }

        // Call a second time to get a second observed value via try/catch
        bool ok2;
        int256 val2;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 v2) {
            ok2 = true;
            val2 = v2;
        } catch {
            ok2 = false;
            val2 = int256(0);
        }

        // The general rule: reference C's getPrice is a view that completes (does not revert) for all inputs
        // so ok and ok2 must both be true for all inputs; and repeated calls should be consistent (val1 == val2).
        // We assert one combined property reading c: that the two observed call outcomes are equal (both success flags and returned values match).
        // This holds for the reference across all inputs; the mutant that returns int256(0) can change observed return values and break consistency for some inputs.
