pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // We fuzz the deciding values that are forwarded to getPrice: identifier, time and ancillary data.
    // The general rule we assert: for any (identifier, time, ancillaryData) two independent external staticcalls
    // to c.getPrice(...) must decode to the same int256 result (idempotence/determinism of view getter).
    // The mutant that unconditionally returns int256(0) can violate this when the reference's non-returning
    // behavior decodes differently from 0; the fuzzer will search for such inputs.
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Keep domain wide: no restrictive vm.assume. However, avoid extremely large ancillaryData that
        // could make the test harness unhappy; bound the size but allow many possibilities.
        // Bound ancillaryData length to a reasonable maximum while still wide.
        if (ancillaryData.length > 512) ancillaryData = slice(ancillaryData, 0, 512);

        // Prepare the calldata for the view call to getPrice(bytes32,uint256,bytes)
        bytes memory callData = abi.encodeWithSelector(
            bytes4(keccak256("getPrice(bytes32,uint256,bytes)")),
            identifier,
            time,
            ancillaryData
        );

        // First staticcall
        (bool ok1, bytes memory ret1) = address(c).staticcall(callData);
        // Second staticcall
        (bool ok2, bytes memory ret2) = address(c).staticcall(callData);

        // If either call reverted, treat the decoded value as a special sentinel by forcing ok flags
        // into the encoded bytes to compare deterministically. We will consider the decoded pair equal
        // only if both calls succeeded and their decoded int256 values match; otherwise they differ.

        bool bothSucceeded = ok1 && ok2;
        int256 v1 = 0;
        int256 v2 = 0;
        if (ok1) {
            // If returned data length is zero, keep v1 as 0 but mark success in bothSucceeded.
            if (ret1.length >= 32) {
                v1 = abi.decode(ret1, (int256));
            } else {
                // leave v1 == 0
            }
        }
        if (ok2) {
            if (ret2.length >= 32) {
                v2 = abi.decode(ret2, (int256));
            } else {
                // leave v2 == 0
            }
        }

        // The property: for all inputs the two calls must both succeed and decode to the same int256.
        // This holds for the reference C (its view is non-reverting and deterministic), but the mutant
        // that always returns int256(0) can make the decoded values differ when the reference returned
        // no data (or different data) — the fuzzer can find such inputs.
        assertTrue(bothSucceeded && v1 == v2);
    }

    // helper: slice bytes
    function slice(bytes memory data, uint256 start, uint256 length) internal pure returns (bytes memory) {
        if (data.length <= start) return "";
        uint256 available = data.length - start;
        if (available < length) length = available;
        bytes memory out = new bytes(length);
        for (uint256 i = 0; i < length; i++) {
            out[i] = data[start + i];
        }
        return out;
    }
}

