    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: identifier, time, ancillaryData
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Keep domain wide: no tight assumes. But avoid absurdly large calldata for forge fuzzer by bounding ancillaryData length.
        // Allow ancillaryData up to 1024 bytes to keep it wide yet practical.
        vm.assume(ancillaryData.length <= 1024);

        // Perform two independent staticcalls to c.getPrice and compare both success flags and decoded int256 results.
        // We must use low-level staticcall to capture the exact returned bytes and success flag, and decode as int256.
        bytes memory sigAndArgs = abi.encodeWithSignature("getPrice(bytes32,uint256,bytes)", identifier, time, ancillaryData);

        (bool success1, bytes memory ret1) = address(c).staticcall(sigAndArgs);
        (bool success2, bytes memory ret2) = address(c).staticcall(sigAndArgs);

        // Decode returned int256 if call succeeded; if not succeeded, we treat decode as zero-length.
        int256 v1 = 0;
        int256 v2 = 0;
        if (success1 && ret1.length >= 32) {
            v1 = abi.decode(ret1, (int256));
        }
        if (success2 && ret2.length >= 32) {
            v2 = abi.decode(ret2, (int256));
        }

        // Single assertion: on the correct reference implementation both staticcalls should have equal success and equal decoded int256.
        // The mutant that always returns int256(0) can cause the decoded int256 to be 0 while the reference's ret bytes may be empty (or differ),
        // so this equality will fail for some inputs under the mutant.
        assertTrue(success1 == success2 && v1 == v2);
    }
}

