    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameters: assertionId and assertedTruthfully
    function testFuzz_property(bytes32 assertionId, bool assertedTruthfully) public {
        // 1) Read a public getter before the call: getAssertionPolicy(assertionId).blockAssertion
        EscalationManagerInterface.AssertionPolicy memory before = c.getAssertionPolicy(assertionId);

        // 2) Call assertionResolvedCallback through this contract as optimistic asserter (set in setUp)
        //    Wrap in try/catch to satisfy the allowed observation methods (though both variants are non-reverting)
        bool ok;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3) Read the same public getter after the call
        EscalationManagerInterface.AssertionPolicy memory afterCall = c.getAssertionPolicy(assertionId);

        // General invariant: the reference implementation does not change public getters after assertionResolvedCallback.
