contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameters: arbitrary assertionId and assertedTruthfully
    function testFuzz_property(bytes32 assertionId, bool assertedTruthfully) public {
        // wide domain; no restrictive assumptions

        // Read the public view before the callback
        EscalationManagerInterface.AssertionPolicy memory beforePolicy = c.getAssertionPolicy(assertionId);

        // Call the callback as the optimistic asserter (set up caller to be the optimistic asserter stored in c)
        address optimistic = address(c.optimisticAsserter());
        vm.prank(optimistic);
        c.assertionResolvedCallback(assertionId, assertedTruthfully);

        // Read the public view after the callback
        EscalationManagerInterface.AssertionPolicy memory afterPolicy = c.getAssertionPolicy(assertionId);

        // The general invariant: the policy returned by getAssertionPolicy must be unchanged by calling assertionResolvedCallback
        assertTrue(
            beforePolicy.blockAssertion == afterPolicy.blockAssertion
            && beforePolicy.arbitrateViaEscalationManager == afterPolicy.arbitrateViaEscalationManager
            && beforePolicy.discardOracle == afterPolicy.discardOracle
            && beforePolicy.validateDisputers == afterPolicy.validateDisputers
        );
    }
}

