pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address public other;

    function setUp() public {
        // deploy c with optimistic asserter = this test contract
        c = new C(address(this));
        other = address(0xBEEF);
    }

    // Fuzzed parameters: assertionId and assertedTruthfully
    function testFuzz_property(bytes32 assertionId, bool assertedTruthfully) public {
        // General rule: only the configured optimisticAsserter (address passed in constructor) may call assertionResolvedCallback successfully;
        // when called by that address it should succeed (not revert); when called by some other address it must revert due to onlyOptimisticAsserter.

        // 1) as the correct optimistic asserter (this contract), call should succeed
        bool ok;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);

        // 2) when called by some other EOA, it must revert; simulate by prank
        vm.prank(other);
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            // If it succeeds for a non-optimistic asserter, that's a violation; we assert false
            assertTrue(false);
        } catch {
            // expected revert, pass
        }
    }
}

