pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // We implement a malicious optimistic asserter that will revert on getAssertion for certain ids.
    MaliciousOptimisticAsserter mal;

    function setUp() public {
        // deploy malicious optimistic asserter and pass its address to C
        mal = new MaliciousOptimisticAsserter();
        c = new C(address(mal));
    }

    // fuzzed parameter: assertionId (bytes32) — the fuzzer will search for values that cause getAssertion to revert
    function testFuzz_property(bytes32 assertionId) public {
        // 1) Keep domain wide; no restrictive assumes.

        // 2) Configure the malicious optimistic asserter to revert for some assertionIds.
        // We'll set it to revert when the high bit of assertionId (first byte) equals 0xFF to create a non-trivial subset
        // The fuzzer can find such an assertionId. We expose this behavior by writing a mapping in the mal contract.
        bool shouldRevert = (assertionId[0] == 0xff);
        mal.setRevertFlag(shouldRevert);

        // Call through as the optimistic asserter (onlyOptimisticAsserter requires msg.sender == optimisticAsserter)
        // The property: reference C should never revert; mutant may revert when optimisticAsserter.getAssertion reverts.
        bool ok;
        try c.assertionResolvedCallback(assertionId, true) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: the reference contract would always succeed (ok==true) for all inputs,
        // but the mutant that calls optimisticAsserter.getAssertion may cause ok==false for some assertionId values.
        // Therefore we assert that the call did not revert (this holds in the reference for all inputs, and fails for
        // the mutant when the malicious optimistic asserter reverts). The fuzzer will find assertionId with first byte 0xff
        // producing a failure on the mutant.
        assertTrue(ok);
    }
}

// Minimal adversarial helper that can revert from getAssertion to simulate a malicious/bug-triggering optimistic asserter
contract MaliciousOptimisticAsserter {
    bool public shouldRevert;

    function setRevertFlag(bool v) external {
        shouldRevert = v;
    }

    // match the interface function used by the mutant: getAssertion(bytes32) external returns (..)
    // We keep signature flexible: return a dummy tuple or revert based on flag.
    function getAssertion(bytes32) external view returns (bytes32) {
        if (shouldRevert) revert("malicious revert");
        return bytes32(0);
    }

    // Provide the other external functions so C can be constructed with this address and onlyOptimisticAsserter checks pass.
    // Not strictly necessary but added for completeness.
    function assertionResolvedCallback(bytes32, bool) external {}
    function assertionDisputedCallback(bytes32) external {}
}
